-- =====================================================================
--  Maruti Suzuki Dealer Lead Conversion Analysis  (simulated data)
--  Problem: Dealerships get plenty of enquiries and test drives, but few
--  turn into sales. Which dealers and models convert poorly?
--  Period covered: Oct 2024 - Sep 2026 | Target: MySQL 8.0.16+
--  Run this whole file once; it drops and recreates the database.
-- =====================================================================

DROP DATABASE IF EXISTS maruti_dealer_db;
CREATE DATABASE maruti_dealer_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE maruti_dealer_db;

-- ---------------------------------------------------------------------
-- 1. DEALERS  (self-join: parent_dealer_id -> dealer_id)
--    parent_dealer_id is NULL for main showrooms, filled for satellite outlets
-- ---------------------------------------------------------------------
CREATE TABLE dealers (
    dealer_id         INT          NOT NULL,
    dealer_name       VARCHAR(100) NOT NULL,
    city              VARCHAR(50)  NOT NULL,
    state             VARCHAR(50)  NOT NULL,
    region            VARCHAR(10)  NOT NULL,
    channel           VARCHAR(10)  NOT NULL,
    opening_date      DATE         NOT NULL,
    parent_dealer_id  INT          NULL,
    CONSTRAINT pk_dealers PRIMARY KEY (dealer_id),
    CONSTRAINT uq_dealer_name UNIQUE (dealer_name),
    CONSTRAINT chk_dealer_region  CHECK (region IN ('North','South','East','West','Central')),
    CONSTRAINT chk_dealer_channel CHECK (channel IN ('Arena','Nexa')),
    CONSTRAINT fk_dealer_parent FOREIGN KEY (parent_dealer_id)
        REFERENCES dealers (dealer_id) ON DELETE SET NULL ON UPDATE CASCADE
);

-- ---------------------------------------------------------------------
-- 2. EMPLOYEES  (self-join: manager_id -> employee_id)
--    Sales Executive -> Team Lead -> Sales Manager
-- ---------------------------------------------------------------------
CREATE TABLE employees (
    employee_id   INT          NOT NULL,
    dealer_id     INT          NOT NULL,
    emp_name      VARCHAR(100) NOT NULL,
    role          VARCHAR(30)  NOT NULL,
    manager_id    INT          NULL,
    joining_date  DATE         NOT NULL,
    CONSTRAINT pk_employees PRIMARY KEY (employee_id),
    CONSTRAINT chk_emp_role CHECK (role IN ('Sales Executive','Team Lead','Sales Manager')),
    CONSTRAINT fk_emp_dealer FOREIGN KEY (dealer_id)
        REFERENCES dealers (dealer_id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_emp_manager FOREIGN KEY (manager_id)
        REFERENCES employees (employee_id) ON DELETE SET NULL ON UPDATE CASCADE
);

-- ---------------------------------------------------------------------
-- 3. CUSTOMERS  (self-join: referred_by_customer_id -> customer_id)
-- ---------------------------------------------------------------------
CREATE TABLE customers (
    customer_id              INT          NOT NULL,
    customer_name            VARCHAR(100) NOT NULL,
    gender                   VARCHAR(10)  NOT NULL,
    age                      TINYINT      NOT NULL,
    city                     VARCHAR(50)  NOT NULL,
    occupation               VARCHAR(30)  NOT NULL,
    income_band              VARCHAR(10)  NOT NULL,
    referred_by_customer_id  INT          NULL,
    CONSTRAINT pk_customers PRIMARY KEY (customer_id),
    CONSTRAINT chk_cust_gender CHECK (gender IN ('Male','Female')),
    CONSTRAINT chk_cust_age    CHECK (age BETWEEN 18 AND 80),
    CONSTRAINT chk_cust_income CHECK (income_band IN ('Below 5L','5-10L','10-20L','20L+')),
    CONSTRAINT fk_cust_referrer FOREIGN KEY (referred_by_customer_id)
        REFERENCES customers (customer_id) ON DELETE SET NULL ON UPDATE CASCADE
);

-- ---------------------------------------------------------------------
-- 4. MODELS
-- ---------------------------------------------------------------------
CREATE TABLE models (
    model_id     INT          NOT NULL,
    model_name   VARCHAR(50)  NOT NULL,
    segment      VARCHAR(30)  NOT NULL,
    channel      VARCHAR(10)  NOT NULL,
    launch_date  DATE         NOT NULL,
    CONSTRAINT pk_models PRIMARY KEY (model_id),
    CONSTRAINT uq_model_name UNIQUE (model_name),
    CONSTRAINT chk_model_channel CHECK (channel IN ('Arena','Nexa'))
);

-- ---------------------------------------------------------------------
-- 5. VARIANTS
-- ---------------------------------------------------------------------
CREATE TABLE variants (
    variant_id         INT            NOT NULL,
    model_id           INT            NOT NULL,
    variant_name       VARCHAR(50)    NOT NULL,
    fuel_type          VARCHAR(20)    NOT NULL,
    transmission       VARCHAR(15)    NOT NULL,
    ex_showroom_price  DECIMAL(10,2)  NOT NULL,
    CONSTRAINT pk_variants PRIMARY KEY (variant_id),
    CONSTRAINT uq_model_variant UNIQUE (model_id, variant_name),
    CONSTRAINT chk_var_fuel  CHECK (fuel_type IN ('Petrol','CNG','Strong Hybrid','Electric')),
    CONSTRAINT chk_var_trans CHECK (transmission IN ('Manual','AMT','Automatic')),
    CONSTRAINT chk_var_price CHECK (ex_showroom_price > 0),
    CONSTRAINT fk_var_model FOREIGN KEY (model_id)
        REFERENCES models (model_id) ON DELETE RESTRICT ON UPDATE CASCADE
);

-- ---------------------------------------------------------------------
-- 6. LEADS  (one row per enquiry; model_id = model the customer asked about)
-- ---------------------------------------------------------------------
CREATE TABLE leads (
    lead_id      INT          NOT NULL,
    customer_id  INT          NOT NULL,
    dealer_id    INT          NOT NULL,
    employee_id  INT          NOT NULL,
    model_id     INT          NOT NULL,
    lead_date    DATE         NOT NULL,
    lead_source  VARCHAR(20)  NOT NULL,
    lead_status  VARCHAR(10)  NOT NULL,
    lost_reason  VARCHAR(40)  NULL,
    CONSTRAINT pk_leads PRIMARY KEY (lead_id),
    CONSTRAINT chk_lead_source CHECK (lead_source IN ('Walk-in','Website','Social Media','Phone Enquiry','Referral','Dealer Event')),
    CONSTRAINT chk_lead_status CHECK (lead_status IN ('Open','Converted','Lost')),
    CONSTRAINT chk_lost_reason CHECK ((lead_status = 'Lost' AND lost_reason IS NOT NULL)
                                   OR (lead_status <> 'Lost' AND lost_reason IS NULL)),
    CONSTRAINT fk_lead_customer FOREIGN KEY (customer_id) REFERENCES customers (customer_id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_lead_dealer   FOREIGN KEY (dealer_id)   REFERENCES dealers (dealer_id)     ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_lead_employee FOREIGN KEY (employee_id) REFERENCES employees (employee_id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_lead_model    FOREIGN KEY (model_id)    REFERENCES models (model_id)       ON DELETE RESTRICT ON UPDATE CASCADE
);

-- ---------------------------------------------------------------------
-- 7. TEST_DRIVES  (0, 1 or 2 per lead; feedback_rating can be NULL)
-- ---------------------------------------------------------------------
CREATE TABLE test_drives (
    test_drive_id    INT          NOT NULL,
    lead_id          INT          NOT NULL,
    variant_id       INT          NOT NULL,
    test_drive_date  DATE         NOT NULL,
    drive_type       VARCHAR(10)  NOT NULL,
    feedback_rating  TINYINT      NULL,
    CONSTRAINT pk_test_drives PRIMARY KEY (test_drive_id),
    CONSTRAINT chk_td_type   CHECK (drive_type IN ('Showroom','Home')),
    CONSTRAINT chk_td_rating CHECK (feedback_rating BETWEEN 1 AND 5),
    CONSTRAINT fk_td_lead    FOREIGN KEY (lead_id)    REFERENCES leads (lead_id)       ON DELETE CASCADE  ON UPDATE CASCADE,
    CONSTRAINT fk_td_variant FOREIGN KEY (variant_id) REFERENCES variants (variant_id) ON DELETE RESTRICT ON UPDATE CASCADE
);

-- ---------------------------------------------------------------------
-- 8. FOLLOW_UPS  (0 to 6 per lead)
-- ---------------------------------------------------------------------
CREATE TABLE follow_ups (
    followup_id    INT          NOT NULL,
    lead_id        INT          NOT NULL,
    employee_id    INT          NOT NULL,
    followup_date  DATE         NOT NULL,
    mode           VARCHAR(20)  NOT NULL,
    outcome        VARCHAR(20)  NOT NULL,
    CONSTRAINT pk_follow_ups PRIMARY KEY (followup_id),
    CONSTRAINT chk_fu_mode    CHECK (mode IN ('Call','WhatsApp','Showroom Visit','Email')),
    CONSTRAINT chk_fu_outcome CHECK (outcome IN ('Interested','Negotiating','Call Back Later','Not Reachable','Not Interested')),
    CONSTRAINT fk_fu_lead     FOREIGN KEY (lead_id)     REFERENCES leads (lead_id)         ON DELETE CASCADE  ON UPDATE CASCADE,
    CONSTRAINT fk_fu_employee FOREIGN KEY (employee_id) REFERENCES employees (employee_id) ON DELETE RESTRICT ON UPDATE CASCADE
);

-- ---------------------------------------------------------------------
-- 9. BOOKINGS  (at most one per lead; variant_id = what was actually booked)
-- ---------------------------------------------------------------------
CREATE TABLE bookings (
    booking_id      INT            NOT NULL,
    lead_id         INT            NOT NULL,
    variant_id      INT            NOT NULL,
    booking_date    DATE           NOT NULL,
    discount_given  DECIMAL(10,2)  NOT NULL DEFAULT 0,
    finance_opted   VARCHAR(3)     NOT NULL,
    booking_status  VARCHAR(10)    NOT NULL,
    delivery_date   DATE           NULL,
    final_price     DECIMAL(10,2)  NOT NULL,
    CONSTRAINT pk_bookings PRIMARY KEY (booking_id),
    CONSTRAINT uq_booking_lead UNIQUE (lead_id),
    CONSTRAINT chk_bk_discount CHECK (discount_given >= 0),
    CONSTRAINT chk_bk_finance  CHECK (finance_opted IN ('Yes','No')),
    CONSTRAINT chk_bk_status   CHECK (booking_status IN ('Pending','Delivered','Cancelled')),
    CONSTRAINT chk_bk_delivery CHECK ((booking_status = 'Delivered' AND delivery_date >= booking_date)
                                   OR (booking_status <> 'Delivered' AND delivery_date IS NULL)),
    CONSTRAINT chk_bk_price    CHECK (final_price > 0),
    CONSTRAINT fk_bk_lead    FOREIGN KEY (lead_id)    REFERENCES leads (lead_id)       ON DELETE CASCADE  ON UPDATE CASCADE,
    CONSTRAINT fk_bk_variant FOREIGN KEY (variant_id) REFERENCES variants (variant_id) ON DELETE RESTRICT ON UPDATE CASCADE
);

-- ---------------------------------------------------------------------
-- 10. DEALER_TARGETS  (monthly unit target per dealer per model;
--     target_month is always the 1st of the month)
-- ---------------------------------------------------------------------
CREATE TABLE dealer_targets (
    target_id     INT   NOT NULL,
    dealer_id     INT   NOT NULL,
    model_id      INT   NOT NULL,
    target_month  DATE  NOT NULL,
    target_units  INT   NOT NULL,
    CONSTRAINT pk_dealer_targets PRIMARY KEY (target_id),
    CONSTRAINT uq_target UNIQUE (dealer_id, model_id, target_month),
    CONSTRAINT chk_tg_units CHECK (target_units > 0),
    CONSTRAINT chk_tg_month CHECK (DAY(target_month) = 1),
    CONSTRAINT fk_tg_dealer FOREIGN KEY (dealer_id) REFERENCES dealers (dealer_id) ON DELETE CASCADE  ON UPDATE CASCADE,
    CONSTRAINT fk_tg_model  FOREIGN KEY (model_id)  REFERENCES models (model_id)   ON DELETE RESTRICT ON UPDATE CASCADE
);

-- =====================================================================
--  DATA  (inserted parent tables first so every foreign key resolves)
-- =====================================================================











